from typing import List
import heapq

class Solution:
    def mincostToHireWorkers(self, quality: List[int], wage: List[int], k: int) -> float:
        workers = sorted([(w / q, q) for w, q in zip(wage, quality)])
        max_heap = []
        sum_quality = 0
        min_cost = float('inf')

        for ratio, q in workers:
            heapq.heappush(max_heap, -q)
            sum_quality += q
            if len(max_heap) > k:
                sum_quality += heapq.heappop(max_heap)
            if len(max_heap) == k:
                min_cost = min(min_cost, ratio * sum_quality)

        return min_cost

class Solution {
public:
    double mincostToHireWorkers(vector<int>& quality, vector<int>& wage, int k) {
        int n = quality.size();
        vector<pair<double, int>> workers(n);
        for (int i = 0; i < n; i++) {
            workers[i] = {(double)wage[i] / quality[i], quality[i]};
        }
        sort(workers.begin(), workers.end());
        priority_queue<int> pq;
        double sum_q = 0;
        double min_cost = 1e18;
        for (auto& [ratio, q] : workers) {
            pq.push(q);
            sum_q += q;
            if ((int)pq.size() > k) {
                sum_q -= pq.top();
                pq.pop();
            }
            if ((int)pq.size() == k) {
                min_cost = min(min_cost, ratio * sum_q);
            }
        }
        return min_cost;
    }
};

class Solution {
    public double mincostToHireWorkers(int[] quality, int[] wage, int k) {
        int n = quality.length;
        double[][] workers = new double[n][2];
        for (int i = 0; i < n; i++) {
            workers[i] = new double[]{(double) wage[i] / quality[i], (double) quality[i]};
        }
        Arrays.sort(workers, (a, b) -> Double.compare(a[0], b[0]));
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        double sumQ = 0;
        double minCost = Double.MAX_VALUE;
        for (double[] worker : workers) {
            double ratio = worker[0];
            int q = (int) worker[1];
            pq.offer(q);
            sumQ += q;
            if (pq.size() > k) {
                sumQ -= pq.poll();
            }
            if (pq.size() == k) {
                minCost = Math.min(minCost, ratio * sumQ);
            }
        }
        return minCost;
    }
}

var mincostToHireWorkers = function(quality, wage, k) {
    const n = quality.length;
    const workers = [];
    for (let i = 0; i < n; i++) {
        workers.push({ ratio: wage[i] / quality[i], q: quality[i] });
    }
    workers.sort((a, b) => a.ratio - b.ratio);
    const qualities = [];
    let sumQ = 0;
    let minCost = Infinity;

    for (const { ratio, q } of workers) {
        qualities.push(q);
        sumQ += q;
        qualities.sort((a, b) => a - b);
        if (qualities.length > k) {
            sumQ -= qualities.pop();
        }
        if (qualities.length === k) {
            minCost = Math.min(minCost, ratio * sumQ);
        }
    }
    return minCost;
};
